CREATE TABLE devices(id VARCHAR2(36) PRIMARY KEY,owner_id VARCHAR2(36) NOT NULL,token VARCHAR2(2000) NOT NULL,platform VARCHAR2(10) NOT NULL CHECK(platform IN ('ANDROID','IOS')),created_at TIMESTAMP WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL);
CREATE INDEX device_owner ON devices(owner_id);
CREATE TABLE deliveries(id VARCHAR2(36) PRIMARY KEY,owner_id VARCHAR2(36) NOT NULL,title VARCHAR2(200) NOT NULL,due_at TIMESTAMP WITH TIME ZONE NOT NULL,status VARCHAR2(20) NOT NULL,attempts NUMBER(3) DEFAULT 0 NOT NULL,next_attempt TIMESTAMP WITH TIME ZONE NOT NULL,delivered_at TIMESTAMP WITH TIME ZONE,created_at TIMESTAMP WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL);
CREATE INDEX delivery_due ON deliveries(status,next_attempt);
